-- Synthetic test data (2,000 customers) for ecommerce_churn_analysis.sql
-- Randomly generated; not real customers.
DROP TABLE IF EXISTS ecommerce_churn;
CREATE TABLE ecommerce_churn (
    CustomerID                  INTEGER PRIMARY KEY,
    Churn                       INTEGER,   -- 1 = churned, 0 = active
    Tenure                      INTEGER,   -- months
    PreferredLoginDevice        VARCHAR(20),
    CityTier                    INTEGER,
    WarehouseToHome             INTEGER,
    PreferredPaymentMode        VARCHAR(20),
    Gender                      VARCHAR(10),
    HourSpendOnApp              REAL,
    NumberOfDeviceRegistered    INTEGER,
    PreferedOrderCat            VARCHAR(30),
    SatisfactionScore           INTEGER,   -- 1-5
    MaritalStatus               VARCHAR(10),
    NumberOfAddress             INTEGER,
    Complain                    INTEGER,   -- 0/1
    OrderAmountHikeFromlastYear INTEGER,
    CouponUsed                  INTEGER,
    OrderCount                  INTEGER,
    DaySinceLastOrder           INTEGER,
    CashbackAmount              REAL
);

BEGIN TRANSACTION;
COMMIT;
